import { validateBlockerLevel } from './BlockerRules.js';

const MECHANIC_COMBO_TYPES = new Set([
    'combo-key', 'combo-sticky-oneway', 'combo-hidden-urgent',
    'combo-connector-queue', 'combo-frozen-colors', 'combo-stuck-priority'
]);

/** Opt-in demonstrations only. Captures the already-installed blocker wrappers. */
export function installMechanicCombos(engine) {
    if (engine._mechanicCombosInstalled) return;
    engine._mechanicCombosInstalled = true;
    const methodNames = [
        'startLevel', 'startClock', 'advanceClock', 'moveItem', 'selectSource',
        'getValidTargets', 'moveBoxToQueue', 'findQueueMatch', 'deliverQueueBox',
        'completeTrayExit', 'startDragWrappedBox', 'dropOnTray', 'checkConditions',
        'shuffleItems', 'removeTray', 'addExtraTray', 'getBox', 'isAccessible',
        'canMoveBlockerItem', 'canDispatchBlockerBox', 'canQueueBlockerBox', 'getBlockerView'
    ];
    const original = {};
    for (const name of methodNames) original[name] = engine[name];
    const inactive = () => ({ enabled: false, type: null, viewSignature: '' });
    let suspendPriorityConditions = 0;
    let inPairTransaction = false;
    engine.mechanicComboState = inactive();
    engine.lastComboError = '';
    engine.onComboUpdated = null;

    const state = () => engine.mechanicComboState;
    const active = () => !!state()?.enabled;
    const canonical = id => original.getBox.call(engine, id);
    const boardBox = id => {
        const box = canonical(id);
        return box && engine.boxes.includes(box) ? box : null;
    };
    const visible = id => original.isAccessible.call(engine, id);
    const deny = message => {
        engine.lastComboError = message;
        engine.lastBlockerError = message;
        return false;
    };
    const seconds = value => Math.ceil(Math.max(0, (value || 0) - 1e-9));
    const blankView = () => ({ badges: [], concealed: false, hiddenSlots: [], frozenSlots: [], blocked: false, queueHeld: false });
    const baseView = id => original.getBlockerView ? original.getBlockerView.call(engine, id) : blankView();

    function prepare(level) {
        const spec = level?.mechanicCombo;
        if (spec === undefined || spec === null) return null;
        const fail = message => { throw new Error(`Invalid mechanic combo: ${message}`); };
        if (!level || !Array.isArray(level.boxes) || !Array.isArray(level.trays) ||
            !spec || !MECHANIC_COMBO_TYPES.has(spec.type)) fail('a supported type, boxes, and trays are required.');
        if (Object.prototype.hasOwnProperty.call(level, 'blockers') && !Array.isArray(level.blockers)) fail('blockers must be an array.');
        if (level.blockers?.length) validateBlockerLevel(level);
        const real = id => Number.isInteger(id) && id >= 0 && id < level.boxes.length;
        const occupied = ref => ref && real(ref.boxId) && Number.isInteger(ref.slot) &&
            ref.slot >= 0 && ref.slot < level.boxes[ref.boxId].items.length;
        const baseRecord = (type, boxId) => (level.blockers || []).find(record =>
            record.type === type && (record.boxId === boxId || record.boxIds?.includes(boxId)));
        const next = { enabled: true, type: spec.type, label: spec.label || spec.type, viewSignature: '' };
        if (spec.type === 'combo-key') {
            const record = baseRecord('locked', spec.lockedBoxId);
            if (!real(spec.keyBoxId) || !record || record.boxId !== spec.lockedBoxId || record.dependsOnBoxId !== spec.keyBoxId) {
                fail('the key must name the ordinary locked box dependency.');
            }
            Object.assign(next, { keyBoxId: spec.keyBoxId, lockedBoxId: spec.lockedBoxId, keyUsed: false });
        } else if (spec.type === 'combo-sticky-oneway') {
            const pair = spec.sticky;
            if (!pair || !real(pair.boxId) || !Array.isArray(pair.slots) || pair.slots.length !== 2 ||
                !occupied({ boxId: pair.boxId, slot: pair.slots[0] }) ||
                !occupied({ boxId: pair.boxId, slot: pair.slots[1] }) || pair.slots[0] === pair.slots[1]) {
                fail('sticky requires two distinct occupied slots.');
            }
            const items = level.boxes[pair.boxId].items;
            const first = items[pair.slots[0]];
            if (first !== items[pair.slots[1]] || !real(spec.oneWayBoxId) || spec.oneWayBoxId === pair.boxId) {
                fail('sticky items must match and the one-way box must be distinct.');
            }
            Object.assign(next, {
                oneWayBoxId: spec.oneWayBoxId,
                pair: { boxId: pair.boxId, slots: pair.slots.slice(), itemId: first, active: true, status: 'linked' }
            });
        } else if (spec.type === 'combo-hidden-urgent') {
            if (!real(spec.urgentBoxId) || !Number.isFinite(spec.duration) || spec.duration <= 0 ||
                baseRecord('hidden-box', spec.urgentBoxId)?.boxId !== spec.urgentBoxId) {
                fail('hidden urgency needs a real base hidden-box and positive duration.');
            }
            next.urgent = { boxId: spec.urgentBoxId, duration: spec.duration, remaining: spec.duration,
                activated: false, completed: false, status: 'waiting' };
        } else if (spec.type === 'combo-connector-queue') {
            const record = baseRecord('connector', spec.boxIds?.[0]);
            if (!Number.isInteger(spec.queueCapacity) || spec.queueCapacity < 2 ||
                !Array.isArray(spec.boxIds) || spec.boxIds.length !== 2 || !spec.boxIds.every(real) ||
                !record || record.boxIds.slice().sort().join(',') !== spec.boxIds.slice().sort().join(',')) {
                fail('connector capacity and both base connector IDs are required.');
            }
            Object.assign(next, { queueCapacity: spec.queueCapacity, connectorBoxIds: spec.boxIds.slice() });
        } else if (spec.type === 'combo-frozen-colors') {
            if (!Number.isFinite(spec.swapAt) || spec.swapAt <= 0 || !occupied(spec.first) || !occupied(spec.second) ||
                (spec.first.boxId === spec.second.boxId && spec.first.slot === spec.second.slot)) {
                fail('color swap needs two occupied physical tokens and a positive time.');
            }
            const firstItem = level.boxes[spec.first.boxId].items[spec.first.slot];
            const secondItem = level.boxes[spec.second.boxId].items[spec.second.slot];
            if (firstItem === secondItem) fail('the initial color swap must exchange different item types.');
            next.swap = {
                at: spec.swapAt, remaining: spec.swapAt, started: false, status: 'pending',
                tooltip: spec.tooltip || 'đổi loại sau4s',
                tokens: [
                    { id: 'first', boxId: spec.first.boxId, slot: spec.first.slot, itemId: firstItem },
                    { id: 'second', boxId: spec.second.boxId, slot: spec.second.slot, itemId: secondItem }
                ]
            };
        } else if (spec.type === 'combo-stuck-priority') {
            const tray = level.trays.find(candidate => candidate.id === spec.priorityTrayId);
            const record = baseRecord('stuck', spec.stuckBoxId);
            if (!real(spec.stuckBoxId) || record?.boxId !== spec.stuckBoxId || !tray ||
                tray.targetItemId !== spec.priorityItemId) fail('priority needs its stuck box and matching real tray.');
            next.priority = { stuckBoxId: spec.stuckBoxId, trayId: spec.priorityTrayId,
                itemId: spec.priorityItemId, gateOpen: false, fulfilled: false };
        }
        return next;
    }

    function syncPriority() {
        if (state().type !== 'combo-stuck-priority') return;
        const priority = state().priority;
        const record = engine.blockerState?.records?.get(priority.stuckBoxId);
        if (record?.released && !canonical(priority.stuckBoxId)) priority.gateOpen = true;
    }

    engine.getMechanicComboView = function() {
        if (!active()) return { enabled: false, type: null };
        const current = state();
        const view = { enabled: true, type: current.type, label: current.label };
        if (current.type === 'combo-key') Object.assign(view, {
            keyBoxId: current.keyBoxId, lockedBoxId: current.lockedBoxId, keyUsed: current.keyUsed
        });
        if (current.pair) view.sticky = { ...current.pair, slots: current.pair.slots.slice() };
        if (current.type === 'combo-sticky-oneway') view.oneWayBoxId = current.oneWayBoxId;
        if (current.urgent) view.urgent = { ...current.urgent, remaining: seconds(current.urgent.remaining) };
        if (current.type === 'combo-connector-queue') view.queueCapacity = engine.maxQueueSize;
        if (current.swap) view.swap = {
            at: current.swap.at, remaining: seconds(current.swap.remaining), started: current.swap.started,
            status: current.swap.status, tooltip: current.swap.status === 'pending'
                ? current.swap.tooltip : current.swap.status === 'completed' ? 'đã đổi loại' : 'đã hủy đổi loại',
            tokens: current.swap.tokens.map(token => ({ ...token }))
        };
        if (current.priority) view.priority = { ...current.priority };
        return view;
    };
    engine.getComboView = engine.getMechanicComboView;

    function notify(force = false) {
        if (!active()) return;
        const current = state();
        const signature = JSON.stringify({
            type: current.type, keyUsed: current.keyUsed, pair: current.pair,
            urgent: current.urgent && [current.urgent.status, current.urgent.activated,
                current.urgent.completed, seconds(current.urgent.remaining)],
            capacity: current.type === 'combo-connector-queue' ? engine.maxQueueSize : null,
            swap: current.swap && [current.swap.status, current.swap.started, seconds(current.swap.remaining), current.swap.tokens],
            priority: current.priority,
            queue: engine.queue.map(box => box.id), columns: engine.columns
        });
        if (!force && signature === current.viewSignature) return;
        current.viewSignature = signature;
        if (engine.onComboUpdated) engine.onComboUpdated(engine.getMechanicComboView());
        else if (engine.onBlockerUpdated) engine.onBlockerUpdated(engine.blockerState);
    }

    function refresh() {
        if (!active()) return;
        const current = state();
        if (current.type === 'combo-key') {
            const record = engine.blockerState?.records?.get(current.lockedBoxId);
            if (record?.unlocked || engine.blockerState?.shipped?.has(current.keyBoxId)) current.keyUsed = true;
        }
        if (current.priority) syncPriority();
        if (engine.gameState === 'PLAYING' && engine.clockStarted) {
            const urgent = current.urgent;
            if (urgent && !urgent.completed && !urgent.activated && visible(urgent.boxId)) {
                urgent.activated = true;
                urgent.status = 'ticking';
                urgent.remaining = urgent.duration;
            }
            if (current.swap && current.swap.status === 'pending') current.swap.started = true;
        }
        notify();
    }

    engine.startLevel = function(levelConfig) {
        const prepared = prepare(levelConfig);
        const previous = state();
        engine.mechanicComboState = prepared || inactive();
        engine.lastComboError = '';
        suspendPriorityConditions = 0;
        inPairTransaction = false;
        let result;
        try {
            result = original.startLevel.call(engine, levelConfig);
        } catch (error) {
            engine.mechanicComboState = previous;
            throw error;
        }
        if (active() && state().type === 'combo-connector-queue') {
            engine.maxQueueSize = state().queueCapacity;
            if (engine.onQueueUpdated) engine.onQueueUpdated(engine.queue);
        }
        refresh();
        notify(true);
        return result;
    };

    engine.startClock = function() {
        if (!active()) return original.startClock.call(engine);
        const result = original.startClock.call(engine);
        refresh();
        return result;
    };

    function sourceLegal(sourceId, sourceSlot) {
        const source = boardBox(sourceId);
        if (engine.gameState !== 'PLAYING' || !source || source.isWrapped || source.isEmpty() ||
            !visible(source.id) || !Number.isInteger(sourceSlot) || sourceSlot < 0 || sourceSlot > 2 ||
            source.slots[sourceSlot] === null || source.slots[sourceSlot] === undefined) return false;
        const view = baseView(source.id);
        if (view.blocked || view.frozenSlots?.map(Number).includes(sourceSlot)) return false;
        return !(state().type === 'combo-sticky-oneway' && source.id === state().oneWayBoxId);
    }

    function ordinaryMoveAllowed(sourceId, sourceSlot, targetId, targetSlot = null) {
        if (!sourceLegal(sourceId, sourceSlot)) return false;
        const source = boardBox(sourceId), target = boardBox(targetId);
        if (!source || !target || source === target || target.isWrapped || !visible(target.id) ||
            !target.canAccept(targetSlot) || baseView(target.id).blocked) return false;
        return !engine.blockerState?.enabled ||
            !!original.canMoveBlockerItem.call(engine, sourceId, sourceSlot, targetId, targetSlot);
    }

    function isPairSource(sourceId, sourceSlot) {
        const pair = state().pair;
        return state().type === 'combo-sticky-oneway' && pair?.active && pair.boxId === Number(sourceId) &&
            pair.slots.includes(sourceSlot);
    }

    engine.canMoveBlockerItem = function(sourceId, sourceSlot, targetId, targetSlot = null) {
        if (!active()) return original.canMoveBlockerItem.call(engine, sourceId, sourceSlot, targetId, targetSlot);
        if (arguments.length < 3 || targetId === undefined) return sourceLegal(sourceId, sourceSlot);
        if (isPairSource(Number(sourceId), sourceSlot)) {
            if (!ordinaryMoveAllowed(sourceId, sourceSlot, targetId, null)) return false;
            const target = boardBox(targetId);
            const free = target.slots.map((item, slot) => item === null ? slot : -1).filter(slot => slot !== -1);
            return free.length >= 2 && (targetSlot === null || free.includes(targetSlot));
        }
        return ordinaryMoveAllowed(sourceId, sourceSlot, targetId, targetSlot);
    };

    engine.selectSource = function(boxId, slotIndex) {
        if (!active()) return original.selectSource.call(engine, boxId, slotIndex);
        if (state().type === 'combo-sticky-oneway' && Number(boxId) === state().oneWayBoxId) {
            return deny('Hộp một chiều chỉ nhận vật, chưa thể lấy vật ra.');
        }
        const result = original.selectSource.call(engine, boxId, slotIndex);
        if (result) { engine.lastComboError = ''; engine.lastBlockerError = ''; }
        refresh();
        return result;
    };

    engine.getValidTargets = function(sourceId) {
        if (!active() || state().type !== 'combo-sticky-oneway') return original.getValidTargets.call(engine, sourceId);
        const source = boardBox(sourceId);
        if (!source || source.id === state().oneWayBoxId || source.isEmpty() || source.isWrapped) return [];
        const selected = engine.selectedSource?.boxId === source.id ? engine.selectedSource.itemIndex : null;
        const slots = selected !== null ? [selected] : source.slots.map((item, slot) => item !== null ? slot : -1).filter(slot => slot !== -1);
        return engine.boxes.filter(target => target !== source && slots.some(slot => {
            if (!ordinaryMoveAllowed(source.id, slot, target.id, null)) return false;
            if (!isPairSource(source.id, slot)) return true;
            return target.slots.filter(item => item === null).length >= 2;
        })).map(target => target.id);
    };

    function moveStickyPair(sourceId, sourceSlot, targetId, targetSlot) {
        if (inPairTransaction) return deny('Thao tác cặp dính đang được xử lý.');
        const pair = state().pair;
        const source = boardBox(sourceId), target = boardBox(targetId);
        if (!source || !target || !ordinaryMoveAllowed(sourceId, sourceSlot, targetId, null)) {
            return deny('Cặp dính chỉ có thể di chuyển cùng nhau giữa hai hộp hợp lệ.');
        }
        const free = target.slots.map((item, slot) => item === null ? slot : -1).filter(slot => slot !== -1);
        if (free.length < 2 || (targetSlot !== null && (!Number.isInteger(targetSlot) || !free.includes(targetSlot)))) {
            return deny('Cặp dính cần đúng hai ô trống ở hộp đích.');
        }
        const landings = targetSlot === null ? free.slice(0, 2) : [targetSlot, free.find(slot => slot !== targetSlot)];
        const sourceSlots = [sourceSlot, pair.slots.find(slot => slot !== sourceSlot)];
        const participating = [...new Set([...engine.boxes, ...engine.queue])];
        const snapshot = {
            boxes: engine.boxes.slice(), queue: engine.queue.slice(), columns: engine.columns.map(column => column.slice()),
            slots: participating.map(box => ({ box, slots: box.slots.slice(), wrapped: box.isWrapped })),
            selected: engine.selectedSource ? { ...engine.selectedSource } : null,
            moveCount: engine.moveCount, gameState: engine.gameState, loseReason: engine.loseReason,
            clockStarted: engine.clockStarted, draggedBoxId: engine.draggedBoxId
        };
        const boxUpdated = engine.onBoxUpdated, boxWrapped = engine.onBoxWrapped;
        const moveUpdated = engine.onMoveCountUpdated, conditions = engine.checkConditions;
        const boxEvents = [], wrapped = [];
        let succeeded = false, thrown = null;
        inPairTransaction = true;
        engine.onBoxUpdated = (...args) => boxEvents.push(args);
        engine.onBoxWrapped = box => { if (!wrapped.includes(box)) wrapped.push(box); };
        engine.onMoveCountUpdated = () => {};
        engine.checkConditions = () => {};
        try {
            for (let index = 0; index < 2; index++) {
                let slot = sourceSlots[index];
                if (source.slots[slot] === null || source.slots[slot] === undefined) {
                    slot = source.slots.findIndex(item => item !== null && item !== undefined);
                }
                if (!original.moveItem.call(engine, source.id, slot, target.id, landings[index])) break;
                if (index === 1) succeeded = true;
            }
        } catch (error) {
            thrown = error;
        } finally {
            engine.onBoxUpdated = boxUpdated;
            engine.onBoxWrapped = boxWrapped;
            engine.onMoveCountUpdated = moveUpdated;
            engine.checkConditions = conditions;
            engine.moveCount = succeeded ? snapshot.moveCount + 1 : snapshot.moveCount;
            if (!succeeded) {
                engine.boxes = snapshot.boxes;
                engine.queue = snapshot.queue;
                engine.columns = snapshot.columns;
                engine.selectedSource = snapshot.selected;
                engine.gameState = snapshot.gameState;
                engine.loseReason = snapshot.loseReason;
                engine.clockStarted = snapshot.clockStarted;
                engine.draggedBoxId = snapshot.draggedBoxId;
                for (const old of snapshot.slots) { old.box.slots = old.slots.slice(); old.box.isWrapped = old.wrapped; }
            }
            inPairTransaction = false;
        }
        if (thrown) throw thrown;
        if (!succeeded) return deny('Không thể di chuyển nguyên cặp; bàn đã được hoàn tác.');
        const changedSlots = target.slots.map((item, slot) => item !== null && snapshot.slots.find(old => old.box === target)?.slots[slot] === null ? slot : -1)
            .filter(slot => slot !== -1);
        pair.boxId = target.id;
        pair.slots = (changedSlots.length === 2 ? changedSlots : landings).slice().sort((a, b) => a - b);
        pair.active = !target.isWrapped;
        pair.status = target.isWrapped ? 'packed' : 'linked';
        engine.lastComboError = '';
        engine.lastBlockerError = '';
        if (moveUpdated) moveUpdated.call(engine, engine.moveCount);
        for (const args of boxEvents) if (boxUpdated) boxUpdated.apply(engine, args);
        for (const box of wrapped) {
            if (boxWrapped) boxWrapped.call(engine, box);
            else if (engine.boxes.includes(box) && box.isWrapped) engine.moveBoxToQueue(box);
        }
        if (!boxWrapped && !engine.onTrayDelivered) while (engine.tryAutoFillTray()) {}
        refresh();
        if (engine.gameState === 'PLAYING') engine.checkConditions();
        return true;
    }

    engine.moveItem = function(sourceId, sourceSlot, targetId, targetSlot = null) {
        if (!active()) return original.moveItem.call(engine, sourceId, sourceSlot, targetId, targetSlot);
        sourceId = Number(sourceId); targetId = Number(targetId);
        if (state().type === 'combo-sticky-oneway' && sourceId === state().oneWayBoxId) {
            return deny('Hộp một chiều chỉ nhận vật, không thể lấy vật ra.');
        }
        if (isPairSource(sourceId, sourceSlot)) return moveStickyPair(sourceId, sourceSlot, targetId, targetSlot);
        const tracked = state().swap?.tokens.find(token => token.boxId === sourceId && token.slot === sourceSlot) || null;
        const target = boardBox(targetId);
        const beforeSlots = target?.slots.slice();
        const fallbackSlot = targetSlot === null ? target?.slots.findIndex(item => item === null) : targetSlot;
        const priorityCall = state().type === 'combo-stuck-priority';
        if (priorityCall) suspendPriorityConditions++;
        let result;
        try { result = original.moveItem.call(engine, sourceId, sourceSlot, targetId, targetSlot); }
        finally { if (priorityCall) suspendPriorityConditions--; }
        if (result && tracked && target) {
            const changed = target.slots.findIndex((item, slot) => beforeSlots[slot] === null && item !== null);
            tracked.boxId = target.id;
            tracked.slot = changed !== -1 ? changed : fallbackSlot;
        }
        if (result) { engine.lastComboError = ''; engine.lastBlockerError = ''; }
        refresh();
        if (priorityCall && result) engine.checkConditions();
        return result;
    };

    engine.moveBoxToQueue = function(boxOrId) {
        if (!active()) return original.moveBoxToQueue.call(engine, boxOrId);
        if (boxOrId && typeof boxOrId === 'object' && canonical(boxOrId.id) !== boxOrId) {
            return deny('Hộp đã cũ hoặc không còn thuộc bàn chơi hiện tại.');
        }
        const id = boxOrId && typeof boxOrId === 'object' ? boxOrId.id : boxOrId;
        const result = original.moveBoxToQueue.call(engine, boxOrId);
        if (result && state().urgent && Number(id) === state().urgent.boxId && !state().urgent.completed) {
            state().urgent.completed = true;
            state().urgent.status = 'completed';
            state().urgent.remaining = 0;
        }
        if (result) { engine.lastComboError = ''; engine.lastBlockerError = ''; }
        refresh();
        return result;
    };

    function priorityBoxMatches(box) {
        const priority = state().priority;
        return !!box && box.items.length > 0 && box.items.every(item => item === priority.itemId);
    }

    function priorityAllowsDelivery(box, tray) {
        syncPriority();
        const priority = state().priority;
        const priorityBox = priorityBoxMatches(box);
        const priorityTray = tray && String(tray.id) === String(priority.trayId);
        if (!priority.gateOpen) return !(priorityTray && priorityBox) && !(priorityBox && tray?.targetItemId === priority.itemId);
        if (priority.fulfilled) return true;
        return priorityTray && priorityBox && tray.targetItemId === priority.itemId;
    }

    function recordPriorityDelivery(box, tray) {
        const priority = state().priority;
        if (priority.gateOpen && !priority.fulfilled && priorityBoxMatches(box) && String(tray.id) === String(priority.trayId)) {
            priority.fulfilled = true;
        }
    }

    engine.canDispatchBlockerBox = function(id) {
        if (!active()) return original.canDispatchBlockerBox.call(engine, id);
        if (!original.canDispatchBlockerBox.call(engine, id)) return false;
        if (state().type !== 'combo-stuck-priority') return true;
        syncPriority();
        const priority = state().priority, box = canonical(id);
        if (!priority.gateOpen) return !priorityBoxMatches(box);
        return priority.fulfilled || priorityBoxMatches(box);
    };

    engine.findQueueMatch = function() {
        if (!active() || state().type !== 'combo-stuck-priority') return original.findQueueMatch.call(engine);
        const trays = engine.conveyor.getAllActiveTrays();
        for (const box of engine.queue) {
            if (!original.canDispatchBlockerBox.call(engine, box.id)) continue;
            for (const tray of trays) {
                if (tray.canAccept(box) && priorityAllowsDelivery(box, tray)) return { box, tray };
            }
        }
        return null;
    };

    engine.deliverQueueBox = function(boxId, trayId) {
        if (!active()) return original.deliverQueueBox.call(engine, boxId, trayId);
        const box = canonical(boxId);
        const tray = engine.conveyor.getAllActiveTrays().find(candidate => String(candidate.id) === String(trayId));
        if (state().type === 'combo-stuck-priority') {
            if (!box || !tray || !original.canDispatchBlockerBox.call(engine, boxId)) return deny('Hộp chờ không còn hợp lệ để giao.');
            if (!priorityAllowsDelivery(box, tray)) return deny('Khay ưu tiên chưa được mở; phải giải phóng hộp kẹt trước.');
        }
        const priorityCall = state().type === 'combo-stuck-priority';
        if (priorityCall) suspendPriorityConditions++;
        let result;
        try { result = original.deliverQueueBox.call(engine, boxId, trayId); }
        finally { if (priorityCall) suspendPriorityConditions--; }
        if (result && priorityCall) recordPriorityDelivery(box, tray);
        refresh();
        if (priorityCall && result) engine.checkConditions();
        return result;
    };

    engine.startDragWrappedBox = function(boxId) {
        if (active() && state().urgent && Number(boxId) === state().urgent.boxId) {
            return deny('Hộp khẩn cấp phải được đưa vào hàng chờ.');
        }
        return original.startDragWrappedBox.call(engine, boxId);
    };

    engine.dropOnTray = function(trayId) {
        if (!active()) return original.dropOnTray.call(engine, trayId);
        const box = engine.draggedBoxId === null ? null : canonical(engine.draggedBoxId);
        if (state().urgent && box?.id === state().urgent.boxId) return deny('Hộp khẩn cấp phải được đưa vào hàng chờ.');
        const tray = engine.conveyor.getAllActiveTrays().find(candidate => String(candidate.id) === String(trayId));
        const priorityCall = state().type === 'combo-stuck-priority';
        if (priorityCall && (!box || !tray || !priorityAllowsDelivery(box, tray))) {
            return deny('Khay ưu tiên chưa được mở hoặc đơn ưu tiên chưa hoàn tất.');
        }
        if (priorityCall) suspendPriorityConditions++;
        let result;
        try { result = original.dropOnTray.call(engine, trayId); }
        finally { if (priorityCall) suspendPriorityConditions--; }
        if (result && priorityCall) recordPriorityDelivery(box, tray);
        refresh();
        if (priorityCall && result) engine.checkConditions();
        return result;
    };

    engine.completeTrayExit = function(trayId) {
        if (!active()) return original.completeTrayExit.call(engine, trayId);
        const priorityCall = state().type === 'combo-stuck-priority';
        if (priorityCall) suspendPriorityConditions++;
        try { original.completeTrayExit.call(engine, trayId); }
        finally { if (priorityCall) suspendPriorityConditions--; }
        refresh();
        if (priorityCall) engine.checkConditions();
    };

    function performColorSwap() {
        const swap = state().swap;
        if (!swap || swap.status !== 'pending') return;
        const resolved = swap.tokens.map(token => {
            const box = boardBox(token.boxId);
            return box && !box.isWrapped && box.slots[token.slot] === token.itemId ? { token, box } : null;
        });
        if (resolved.some(entry => !entry) ||
            (resolved[0].box === resolved[1].box && resolved[0].token.slot === resolved[1].token.slot)) {
            swap.status = 'cancelled';
            swap.remaining = 0;
            return;
        }
        const first = resolved[0], second = resolved[1];
        const firstValue = first.box.slots[first.token.slot];
        const secondValue = second.box.slots[second.token.slot];
        first.box.slots[first.token.slot] = secondValue;
        second.box.slots[second.token.slot] = firstValue;
        first.token.itemId = secondValue;
        second.token.itemId = firstValue;
        swap.status = 'completed';
        swap.remaining = 0;
        const affected = [...new Set(resolved.map(entry => entry.box))];
        const wrapped = [];
        for (const box of affected) {
            const didWrap = box.checkWrapped();
            if (engine.onBoxUpdated) engine.onBoxUpdated(box);
            if (didWrap) wrapped.push(box);
        }
        for (const box of wrapped) {
            if (engine.onBoxWrapped) engine.onBoxWrapped(box);
            else if (engine.boxes.includes(box)) engine.moveBoxToQueue(box);
        }
        if (!engine.onBoxWrapped && !engine.onTrayDelivered) while (engine.tryAutoFillTray()) {}
    }

    function nextComboExpiry() {
        let next = Infinity;
        const urgent = state().urgent;
        if (urgent?.activated && !urgent.completed && urgent.status === 'ticking') next = Math.min(next, urgent.remaining);
        const swap = state().swap;
        if (swap?.started && swap.status === 'pending') next = Math.min(next, swap.remaining);
        return next;
    }

    function tickCombo(delta) {
        const urgent = state().urgent;
        if (urgent?.activated && !urgent.completed && urgent.status === 'ticking') {
            urgent.remaining = Math.max(0, urgent.remaining - delta);
            if (urgent.remaining <= 1e-9 && engine.gameState === 'PLAYING') {
                urgent.remaining = 0;
                urgent.status = 'expired';
                engine.loseReason = 'Hết giờ khẩn cấp! Hộp ẩn chưa kịp được đưa vào hàng chờ.';
                engine.setGameState('LOST');
            }
        }
        const swap = state().swap;
        if (engine.gameState === 'PLAYING' && swap?.started && swap.status === 'pending') {
            swap.remaining = Math.max(0, swap.remaining - delta);
            if (swap.remaining <= 1e-9) performColorSwap();
        }
    }

    engine.advanceClock = function(deltaSeconds) {
        if (!active()) return original.advanceClock.call(engine, deltaSeconds);
        if (engine.gameState !== 'PLAYING' || !engine.clockStarted || !Number.isFinite(deltaSeconds) ||
            deltaSeconds <= 0 || !engine.hasPlayerWorkRemaining()) return;
        let remainingDelta = deltaSeconds;
        refresh();
        for (let iteration = 0; iteration < 512 && remainingDelta > 1e-9 && engine.gameState === 'PLAYING'; iteration++) {
            let expiry = nextComboExpiry();
            if (expiry <= 1e-9) {
                tickCombo(0);
                refresh();
                expiry = nextComboExpiry();
                if (expiry <= 1e-9 || engine.gameState !== 'PLAYING') break;
            }
            const step = Math.min(remainingDelta, expiry);
            if (!(step > 1e-9)) break;
            original.advanceClock.call(engine, step);
            if (engine.gameState !== 'PLAYING') break;
            tickCombo(step);
            remainingDelta -= step;
            refresh();
        }
        refresh();
        if (engine.gameState === 'PLAYING') engine.checkConditions();
    };

    function priorityConditions() {
        if (engine.gameState !== 'PLAYING' || suspendPriorityConditions > 0) return;
        refresh();
        if (engine.hasPendingTrayExits()) return;
        const priority = state().priority;
        const record = engine.blockerState?.records?.get(priority.stuckBoxId);
        const noStuck = !!record?.released;
        if (engine.boxes.every(box => box.isEmpty()) && engine.queue.length === 0 && noStuck &&
            !engine.conveyor.hasRemainingTrays()) {
            engine.setGameState('WON');
            return;
        }
        if (engine.queue.length > engine.maxQueueSize) {
            engine.loseReason = 'Hàng chờ vượt quá sức chứa.';
            engine.setGameState('LOST');
            return;
        }
        if (engine.findQueueMatch()) return;
        const trays = engine.conveyor.getAllActiveTrays();
        for (const box of engine.boxes) {
            if (!box.isWrapped) continue;
            if (original.canQueueBlockerBox.call(engine, box.id)) return;
            if (visible(box.id) && !baseView(box.id).blocked && trays.some(tray => tray.canAccept(box) && priorityAllowsDelivery(box, tray))) return;
        }
        for (const source of engine.boxes) {
            for (let slot = 0; slot < source.slots.length; slot++) {
                if (source.slots[slot] === null) continue;
                for (const target of engine.boxes) {
                    if (source !== target && ordinaryMoveAllowed(source.id, slot, target.id, null)) return;
                }
            }
        }
        engine.loseReason = engine.queue.length >= engine.maxQueueSize
            ? 'Hàng chờ đầy và khay ưu tiên vẫn đang bị khóa.'
            : 'Không còn nước đi hoặc lượt giao hợp lệ; đơn ưu tiên bị chặn.';
        engine.setGameState('LOST');
    }

    engine.checkConditions = function() {
        if (!active()) return original.checkConditions.call(engine);
        if (state().type === 'combo-stuck-priority') return priorityConditions();
        return original.checkConditions.call(engine);
    };

    engine.addExtraTray = function() {
        if (!active()) return original.addExtraTray.call(engine);
        const oldCapacity = engine.maxQueueSize;
        const result = original.addExtraTray.call(engine);
        if (result && state().type === 'combo-connector-queue') engine.maxQueueSize = oldCapacity + 1;
        refresh();
        return result;
    };
    engine.shuffleItems = function(...args) {
        if (!active()) return original.shuffleItems.apply(engine, args);
        if (state().pair || state().swap) return engine._boosterFail('Không thể xáo các vật đang thuộc cơ chế kết hợp.');
        const result = original.shuffleItems.apply(engine, args);
        refresh();
        return result;
    };
    engine.removeTray = function(...args) {
        if (!active()) return original.removeTray.apply(engine, args);
        if (state().pair || state().swap) return engine._boosterFail('Không thể xóa khay khi cơ chế vật lý kết hợp đang theo dõi vật.');
        const result = original.removeTray.apply(engine, args);
        refresh();
        return result;
    };

    engine.canQueueBlockerBox = function(id) {
        return original.canQueueBlockerBox ? original.canQueueBlockerBox.call(engine, id) : false;
    };

    engine.getBlockerView = function(boxId) {
        const base = baseView(boxId) || blankView();
        if (!active()) return base;
        const box = canonical(boxId), id = Number(boxId);
        const badges = [...(base.badges || [])];
        const add = badge => { if (!badges.includes(badge)) badges.push(badge); };
        const current = state();
        let queueHeld = !!base.queueHeld;
        if (current.type === 'combo-key' && id === current.keyBoxId) add(current.keyUsed ? 'chìa khóa đã dùng' : `chìa khóa hộp ${current.lockedBoxId}`);
        if (current.type === 'combo-sticky-oneway') {
            if (current.pair?.boxId === id) add(current.pair.status === 'packed' ? 'cặp dính đã đóng gói' : 'cặp dính: di chuyển cùng nhau');
            if (id === current.oneWayBoxId) add('một chiều: chỉ nhận');
        }
        if (current.urgent && id === current.urgent.boxId) {
            add(current.urgent.completed ? 'khẩn cấp đã vào hàng chờ' : `khẩn ẩn ${seconds(current.urgent.remaining)}s`);
        }
        if (current.type === 'combo-connector-queue' && current.connectorBoxIds.includes(id)) add(`hàng chờ tối đa ${engine.maxQueueSize}`);
        if (current.swap && current.swap.tokens.some(token => token.boxId === id)) {
            add(current.swap.status === 'pending' ? current.swap.tooltip : current.swap.status === 'completed' ? 'đã đổi loại' : 'đã hủy đổi loại');
        }
        if (current.priority) {
            if (id === current.priority.stuckBoxId) add('nhả hộp để mở khay ưu tiên');
            if (box && engine.queue.includes(box) && !engine.canDispatchBlockerBox(box.id)) queueHeld = true;
        }
        return {
            ...base, badges,
            hiddenSlots: (base.hiddenSlots || []).map(entry => typeof entry === 'number' ? entry : { ...entry }),
            frozenSlots: (base.frozenSlots || []).map(Number),
            blocked: !!base.blocked, queueHeld,
            comboType: current.type,
            stickySlots: current.pair?.active && current.pair.boxId === id ? current.pair.slots.slice() : [],
            oneWay: current.type === 'combo-sticky-oneway' && id === current.oneWayBoxId,
            keyForBoxId: current.type === 'combo-key' && id === current.keyBoxId ? current.lockedBoxId : null
        };
    };
}

